(16414,0,2,'How dare you disturb the master\'s dinner!',12,0,100,0,0,0,'Ghostly Steward'),
(16414,0,3,'How dare you spill the master\'s wine!',12,0,100,0,0,0,'Ghostly Steward - On Death'),
(16414,1,0,'Impudent outsiders!',12,0,100,0,0,0,'Ghostly Steward - On Aggro'),
(16414,1,1,'Meddling fools! You will pay with your lives!',12,0,100,0,0,0,'Ghostly Steward - On Aggro'),
(16414,1,2,'You\'ll never make it out alive....',12,0,100,0,0,0,'Ghostly Steward - On Aggro'),
(16460,0,0,'He asked if the imp could join in--can you believe it? Actually, it wasn\'t half bad....',12,0,100,1,0,0,'Night Mistress'),
