(43377,0,0,'I haven\'t got any money!  Get away!',14,0,100,0,0,0,'Ephram "Midriff" Moonfall'),
(43505,0,0,'%s breathes a heavy sigh of relief.',16,0,100,0,0,0,'Bossy'),
(44414,0,0,'Hellscream\'s involved, you say?',12,0,100,6,0,0,'Durak'),
(44414,1,0,'Well then there is only one thing left to be done...',12,0,100,1,0,0,'Durak'),
(44414,2,0,'This is all happening sooner than I would have liked.',12,0,100,1,0,0,'Durak'),
(44414,3,0,'I am afraid that you, $n, have outgrown your usefulness...',12,0,100,1,0,0,'Durak'),
(45162,0,0,'Fine.  You want some of this?',12,0,100,0,0,0,'Hearthglen Trainee'),
(45162,0,1,'The time for the Crusade is now!',12,0,100,0,0,0,'Hearthglen Trainee'),
(45162,0,2,'Fine... but I won\'t hold back!',12,0,100,0,0,0,'Hearthglen Trainee'),
(45162,0,3,'Get ready, \'cause here I come!',12,0,100,0,0,0,'Hearthglen Trainee'),
(45162,1,0,'Well fought.',12,0,100,0,0,0,'Hearthglen Trainee'),
(45162,1,1,'I suppose I need some more practice.',12,0,100,0,0,0,'Hearthglen Trainee'),
